-- Original biome1 terrain areas (fBm.gxf), not building slots (gxg).
-- Only learned furniture with an absent original placement criterion is eligible.
CREATE TABLE haven_ranch_furniture (
    owner_character_id bigint NOT NULL REFERENCES haven_bags(character_id) ON DELETE CASCADE,
    map_id integer NOT NULL CHECK (map_id=1440),
    item_uid bigint PRIMARY KEY CHECK (item_uid>0),
    item_ref integer NOT NULL CHECK (item_ref>0),
    template_id bigint NOT NULL CHECK (template_id>0),
    area_id integer NOT NULL CHECK (area_id BETWEEN 1 AND 4),
    direction integer NOT NULL CHECK (direction BETWEEN 0 AND 7),
    x integer NOT NULL,
    y integer NOT NULL,
    z smallint NOT NULL CHECK (z BETWEEN -511 AND 512),
    UNIQUE(owner_character_id,map_id,x,y)
);
